/bin/zsh -lc "python3 -c 'import itertools
requests=[(1,2,1),(2,3,2),(1,3,1)]
for order in itertools.permutations(range(3)):
    capacity=[3,2,4]
    answer=0
    for i in order:
        l,r,d=requests[i]
        if any(capacity[j]<d for j in range(l-1,r)):
            answer=i+1
            break
        for j in range(l-1,r):
            capacity[j]-=d
    print(\"顺序\", tuple(i+1 for i in order), \"输出\", answer)'"

